// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { addToSelection, toggleInSelection } from "../../../main/frontend/graph-explorer/graph-selection.ts";

test("a click on one node and a ⌘-click on another select both", () => {
  assert.deepEqual([...toggleInSelection(new Set(), "b", "a")].sort(), ["a", "b"]);
});

test("a ⌘-click toggles the node; the clicked node joins the selection once", () => {
  assert.deepEqual([...toggleInSelection(new Set(["x"]), "b", "a")].sort(), ["a", "b", "x"]);
  assert.deepEqual([...toggleInSelection(new Set(["a", "b"]), "b", "a")], ["a"]);
  assert.deepEqual([...toggleInSelection(new Set(["a", "b"]), "a", null)], ["b"]);
  // A ⌘-click on the clicked node itself selects it alone.
  assert.deepEqual([...toggleInSelection(new Set(), "a", "a")], ["a"]);
});

test("a box adds what it touches and the clicked node; an unchanged selection is the same set", () => {
  assert.deepEqual([...addToSelection(new Set(["x"]), ["b", "c"], "a")].sort(), ["a", "b", "c", "x"]);
  const current = new Set(["a", "b"]);
  assert.equal(addToSelection(current, ["b"], "a"), current);
  assert.equal(addToSelection(current, [], null), current);
});
